package com.bitpoint.homeservercontrol;

import android.app.*;import android.content.*;import android.content.pm.ProviderInfo;import android.content.res.Configuration;import android.graphics.*;import android.graphics.drawable.*;import android.net.Uri;import android.os.Looper;import android.provider.DocumentsContract;import android.view.*;import android.widget.*;
