@RunWith(RobolectricTestRunner.class) @Config(sdk=30,qualifiers="ru-rRU-w411dp-h890dp-mdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class FileAppearanceTest {
 private android.app.Application app;private TransferForegroundService.State old;private Configuration original;
 @Before public void setup()throws Exception{
  app=RuntimeEnvironment.getApplication();original=new Configuration(app.getResources().getConfiguration());old=TransferForegroundService.state;app.getSharedPreferences(ServerConfig.PREFS,0).edit().clear().commit();app.getSharedPreferences(EmbeddedServerService.PREFS,0).edit().clear().commit();ConfigMigrator.migrate(app);
  LastModIntegrationTest.Documents p=new LastModIntegrationTest.Documents();p.root=Files.createTempDirectory(app.getCacheDir().toPath(),"files-appearance-").toFile();new File(p.root,"Чертежи").mkdir();
  for(String name:new String[]{"Фото.jpg","Документы.pdf","Проект.dwg","Архив.zip","Видео.mp4"})Files.write(new File(p.root,name).toPath(),new byte[24]);
  ProviderInfo info=new ProviderInfo();info.authority="appearance.documents";info.name=LastModIntegrationTest.Documents.class.getName();info.packageName=app.getPackageName();info.applicationInfo=app.getApplicationInfo();info.exported=true;info.grantUriPermissions=true;info.readPermission=android.Manifest.permission.MANAGE_DOCUMENTS;info.writePermission=android.Manifest.permission.MANAGE_DOCUMENTS;p.attachInfo(app,info);ShadowContentResolver.registerProviderInternal(info.authority,p);
  Uri tree=DocumentsContract.buildTreeDocumentUri(info.authority,"root");app.getSharedPreferences(EmbeddedServerService.PREFS,0).edit().putString(FileNodes.PHONE_TREE,tree.toString()).commit();File share=EmbeddedServerService.share(app);share.mkdirs();Files.write(new File(share,"Сервера.pdf").toPath(),new byte[36]);TransferForegroundService.state=new TransferForegroundService.State(false,false,"Передач пока нет","",0,0,0);
 }
 @After public void cleanup(){TransferForegroundService.state=old;app.getResources().updateConfiguration(original,app.getResources().getDisplayMetrics());}
 private org.robolectric.android.controller.ActivityController<FilesActivity> screen(){return Robolectric.buildActivity(FilesActivity.class,new Intent(app,FilesActivity.class).putExtra("own_server",true)).create();}
 private void ready(FilesActivity a)throws Exception{long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(8);while(System.nanoTime()<end){Shadows.shadowOf(Looper.getMainLooper()).idle();if(ReflectionHelpers.<Boolean>getField(a,"phoneReady")&&ReflectionHelpers.<Boolean>getField(a,"remoteReady"))return;Thread.sleep(5);}fail("File panes did not load");}
 @Test public void glassAndLightFilesFitSelectionAndTransferStates()throws Exception{
  int cases=0;
  for(int theme:new int[]{0,1,4})for(boolean glass:new boolean[]{false,true})for(float font:new float[]{1,2})for(int[] size:new int[][]{{360,640},{640,300},{1280,800},{800,1280}}){
   Configuration cfg=new Configuration(original);cfg.fontScale=font;cfg.screenWidthDp=size[0];cfg.screenHeightDp=size[1];app.getResources().updateConfiguration(cfg,app.getResources().getDisplayMetrics());ThemeCatalog.select(app,theme);ThemeCatalog.glass(app,glass);
   TransferForegroundService.state=new TransferForegroundService.State(false,false,"Передач пока нет","",0,0,0);
   try(var controller=screen()){FilesActivity a=controller.get();ready(a);View root=root(a);ListView list=a.findViewById(R.id.phoneFileList);int at=0;for(int i=0;i<list.getCount();i++)if(list.getItemAtPosition(i).toString().contains("Документы.pdf"))at=i;FileEntryRow row=(FileEntryRow)list.getAdapter().getView(at,null,list);((CheckBox)row.getChildAt(0)).performClick();assertTrue(ReflectionHelpers.<TextView>getField(a,"phonePath").getText().toString().contains("Выбрано: 1"));
    TransferForegroundService.State[] states={new TransferForegroundService.State(false,false,"Передач пока нет","",0,0,0),new TransferForegroundService.State(false,true,"Сохранено незавершённых заданий: 2. Открой очередь для продолжения.","",0,0,2),new TransferForegroundService.State(false,true,"Передача не завершена. Исходники сохранены. Проверь сеть, папку и свободное место.","TEST",0,0,0),new TransferForegroundService.State(true,false,"Передача: 68 МБ / 100 МБ","",68,100,1)};
    for(int i=0;i<states.length;i++){TransferForegroundService.state=states[i];ReflectionHelpers.callInstanceMethod(a,"renderTransfer");layout(root,size[0],size[1]);assertEquals("Progress follows the chosen theme",ThemeCatalog.color(a,com.bitpoint.homeservercontrol.ui.R.attr.hscAccent),ReflectionHelpers.<ProgressBar>getField(a,"progress").getProgressTintList().getDefaultColor());inside(root,(ViewGroup)root);if(size[0]>=600&&size[1]>=400){View phoneNav=((ViewGroup)ReflectionHelpers.<TextView>getField(a,"phonePath").getParent()).getChildAt(1);View serverNav=((ViewGroup)ReflectionHelpers.<TextView>getField(a,"serverPath").getParent()).getChildAt(1);assertEquals("Tablet file toolbars align with selection on one side",phoneNav.getTop(),serverNav.getTop());}for(String field:new String[]{"send","receive","phoneTab","serverTab"}){Button b=ReflectionHelpers.getField(a,field);assertTrue("48dp "+field,b.getHeight()>=48);assertTrue("Caption fits "+b.getText(),b.getLayout().getHeight()<=b.getHeight()-b.getCompoundPaddingTop()-b.getCompoundPaddingBottom());}
     for(int id:new int[]{R.id.phoneFileList,R.id.remoteFileList}){View frame=(View)a.findViewById(id).getParent();if(((View)frame.getParent()).getVisibility()==View.VISIBLE)assertTrue("List remains usable "+Arrays.toString(size)+" glass="+glass+" font="+font+" state="+i+" h="+frame.getHeight(),frame.getHeight()>=(size[1]<400?80:160));}
     if(glass){LinearLayout pane=ReflectionHelpers.getField(a,"phonePane");assertTrue(pane.getBackground() instanceof GradientDrawable);assertTranslucent((GradientDrawable)pane.getBackground());Button tab=ReflectionHelpers.getField(a,"phoneTab");assertTrue(tab.getBackground() instanceof FileControlDrawable);assertTranslucent((GradientDrawable)tab.getBackground());assertNull(tab.getBackgroundTintList());TextView status=a.findViewById(R.id.transferStatusText);assertTranslucent((GradientDrawable)status.getBackground());}
     if(theme==4)assertEquals("Light background survives glass",0xFFF3F4F6,((ColorDrawable)root.getBackground()).getColor());
     if(glass&&font==1&&(theme==0||theme==4)&&(size[0]==360||size[0]==1280)&&i==1)capture(root,(theme==4?"light":"dark")+"-"+size[0]+"x"+size[1]);cases++;
    }
   }
  }
  assertEquals(192,cases);
 }
 @Test public void queueResumeOpensQueueDirectlyAndErrorsKeepFullDetails()throws Exception{
  try(var c=screen()){FilesActivity a=c.get();ready(a);TransferForegroundService.state=new TransferForegroundService.State(false,true,"Сохранено незавершённых заданий: 2. Открой очередь для продолжения.","",0,0,2);ReflectionHelpers.callInstanceMethod(a,"renderTransfer");TextView status=a.findViewById(R.id.transferStatusText);assertEquals("В очереди: 2 · Продолжить ›",status.getText());status.performClick();assertEquals(TransferQueueActivity.class.getName(),Shadows.shadowOf(a).getNextStartedActivity().getComponent().getClassName());
   TransferForegroundService.state=new TransferForegroundService.State(false,true,"Передача не завершена. Исходники сохранены. Проверь сеть.","EXACT_DIAGNOSTIC",0,0,0);ReflectionHelpers.callInstanceMethod(a,"renderTransfer");status.performClick();String text=((TextView)ShadowAlertDialog.getLatestAlertDialog().findViewById(android.R.id.message)).getText().toString();assertTrue(text.contains("Исходники сохранены"));assertTrue(text.contains("EXACT_DIAGNOSTIC"));assertNull(status.getEllipsize());
   boolean autoError=AutoReceive.error;try{AutoReceive.error=true;TransferForegroundService.state=new TransferForegroundService.State(false,false,"Готово. Файлы скопированы.","",0,0,0);ReflectionHelpers.callInstanceMethod(a,"renderTransfer");assertTrue("Automatic save errors cannot be labelled done",status.getText().toString().startsWith("Ошибка сохранения."));TransferForegroundService.state=new TransferForegroundService.State(false,true,"Сохранено незавершённых заданий: 2. Открой очередь для продолжения.","",0,0,2);ReflectionHelpers.callInstanceMethod(a,"renderTransfer");assertTrue("Saved queue cannot conceal an incoming save failure",status.getText().toString().startsWith("Ошибка сохранения."));status.performClick();assertNull("Error opens details instead of silently navigating to queue",Shadows.shadowOf(a).getNextStartedActivity());}finally{AutoReceive.error=autoError;}
  }
 }
 @Test public void lightGlassRetainsLightSystemColorsAndDoesNotChangeConnectionSettings(){
  var prefs=app.getSharedPreferences(ServerConfig.PREFS,0);prefs.edit().putString("identity_marker","preserve").putString(ServerConfig.KEY_LOCAL_HOST,"192.0.2.44").putString("host-key-marker","preserve").commit();ThemeCatalog.select(app,4);ThemeCatalog.glass(app,true);var before=new HashMap<>(prefs.getAll());
  try(var c=screen()){FilesActivity a=c.get();assertTrue(ThemeCatalog.lightGlass(a));assertEquals(0xFFF3F4F6,ThemeCatalog.color(a,com.bitpoint.homeservercontrol.ui.R.attr.hscBackground));assertEquals(0xFF20242B,ThemeCatalog.color(a,com.bitpoint.homeservercontrol.ui.R.attr.hscTextPrimary));assertEquals(0xFFF3F4F6,a.getWindow().getNavigationBarColor());assertTrue((a.getWindow().getDecorView().getSystemUiVisibility()&View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR)!=0);assertEquals(8,ThemeCatalog.IDS.length);assertEquals("light",ThemeCatalog.IDS[4]);assertEquals("Светлый фон",ThemeCatalog.NAMES[4]);assertEquals(before,prefs.getAll());}
 }
 @Test @Config(sdk=24) public void lightThemeKeepsNavigationReadableBeforeDarkNavigationIcons(){ThemeCatalog.select(app,4);ThemeCatalog.glass(app,true);try(var c=screen()){assertEquals(0xFF211B2A,c.get().getWindow().getNavigationBarColor());}}
 @Test public void qrEyeIconsHaveMatchingGeometryAndClearSlash()throws Exception{
  for(boolean glass:new boolean[]{false,true})for(int shape=0;shape<4;shape++){ThemeCatalog.glass(app,glass);IconShapeCatalog.select(app,shape);Context themed=new ContextThemeWrapper(app,ThemeCatalog.style(app));FileEntryRow row=new FileEntryRow(themed);Drawable bg=row.getChildAt(row.getChildCount()-1).getBackground();if(glass){assertTrue(bg instanceof FileControlDrawable);assertEquals(GradientDrawable.RECTANGLE,((GradientDrawable)bg).getShape());}else{assertTrue(bg instanceof ButtonOutlineDrawable);android.graphics.Outline frame=new android.graphics.Outline();bg.setBounds(0,0,80,48);bg.getOutline(frame);assertEquals(12,frame.getRadius(),0);}}
  ThemeCatalog.glass(app,false);ThemeCatalog.select(app,0);Context c=new ContextThemeWrapper(app,ThemeCatalog.style(app));Bitmap sheet=Bitmap.createBitmap(320,160,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(sheet);canvas.drawColor(0xFF211A2B);
  for(int i=0;i<2;i++){Drawable icon=c.getDrawable(i==0?com.bitpoint.homeservercontrol.ui.R.drawable.ic_action_eye:com.bitpoint.homeservercontrol.ui.R.drawable.ic_action_eye_off).mutate();icon.setTint(0xFFBD88FF);icon.setBounds(16+160*i,16,144+160*i,144);icon.draw(canvas);}
  assertTrue("Slash starts near upper left",Color.red(sheet.getPixel(192,32))>80);File dir=new File("build/ui-previews/files-1.28-20261027");dir.mkdirs();try(var out=new FileOutputStream(new File(dir,"qr-eye-icons.png"))){assertTrue(sheet.compress(Bitmap.CompressFormat.PNG,100,out));}finally{sheet.recycle();}
 }
 private void assertTranslucent(GradientDrawable d){assertNotNull(d.getColors());for(int color:d.getColors())assertTrue("Glass fill stays translucent",Color.alpha(color)>0&&Color.alpha(color)<255);}
 private View root(Activity a){return ((ViewGroup)a.findViewById(android.R.id.content)).getChildAt(0);}
 private void force(View v){v.forceLayout();if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)force(((ViewGroup)v).getChildAt(i));}
 private void layout(View v,int w,int h){force(v);v.measure(View.MeasureSpec.makeMeasureSpec(w,1073741824),View.MeasureSpec.makeMeasureSpec(h,1073741824));v.layout(0,0,w,h);}
 private void inside(View v,ViewGroup root){if(v.getVisibility()!=View.VISIBLE)return;Rect r=new Rect();v.getDrawingRect(r);root.offsetDescendantRectToMyCoords(v,r);assertTrue("Element stays in viewport "+v+" "+r,r.left>=0&&r.top>=0&&r.right<=root.getWidth()&&r.bottom<=root.getHeight());if(v instanceof ViewGroup&&!(v instanceof ListView))for(int i=0;i<((ViewGroup)v).getChildCount();i++)inside(((ViewGroup)v).getChildAt(i),root);}
 private void settle(View v){v.jumpDrawablesToCurrentState();if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)settle(((ViewGroup)v).getChildAt(i));}
 private void capture(View v,String name)throws Exception{settle(v);Bitmap b=Bitmap.createBitmap(v.getWidth(),v.getHeight(),Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));File dir=new File("build/ui-previews/files-1.28-20261027");dir.mkdirs();try(var out=new FileOutputStream(new File(dir,name+".png"))){assertTrue(b.compress(Bitmap.CompressFormat.PNG,100,out));}finally{b.recycle();}}
}
